contract InvMutTest {
	C c;
	constructor(C _c) { c = _c; }

	function test(uint256 amount) public {
		require(address(this).balance >= amount, "need funds");
		bool ok;
		(ok, ) = address(c).call{value: amount}(abi.encodeWithSignature("go()"));
		// On P, go() aborts with revert() when the target call fails, so the
		// outer call can never complete successfully. On M the revert is
		// removed, so go() completes and transfers the funds out instead.
		assert(!ok);
	}

	receive() external payable {}
	fallback() external payable {}
}

