	function test(uint256 extra, uint256 v) public {
		require(address(this).balance >= extra + v);
		// seed c with leftover ether via its payable fallback
		(bool ok, ) = address(c).call{value: extra}("");
		require(ok);
		c.go{value: v}();
		assert(address(c).balance == 0);
	}
}

